local _, WFJ = ...
WFJ.Data.add("book", {
  ["8402defc612c0c78"] = { "Questa è una riproduzione in scala dello scheletro di Toothgnasher. Il leggendario ariete era una meraviglia di Khaz Modan e il protagonista di molti racconti del folclore nanico. Ancora oggi gli ecologisti non sanno spiegarsi le dimensioni mostruose né la resistenza fisica dell'ariete.", "." },
  ["841463513ccb289a"] = { "Spinto dal desiderio di imparare tutto ciò che poteva sul mondo della magia e sulle sue oscure meraviglie, era insofferente verso quelli che riteneva i precetti antiquati e privi di fantasia dei suoi pari. Quando udì il potente richiamo dalla Nordania, l'arcimago piegò tutta la sua considerevole volontà a comunicare con la voce misteriosa. Convinto che il Kirin Tor fosse troppo schizzinoso per afferrare il potere e la conoscenza insiti nelle arti oscure, decise di imparare ciò che poteva dal potentissimo Re dei Lich.", "." },
  ["844f626f64483285"] = { "JARIEN E SOTHOS\n\nFratelli e aspiranti membri della ⟦Scarlet Crusade=Crociata Scarlatta⟧\n\nJarien e Sothos erano due delle persone più intolleranti che abbia mai conosciuto. Eppure come combattenti erano eccezionali, e venivano da una famiglia ricca: suppongo sia per questo che Anthion, il capo di The Veiled Blade, li tenne con sé.\n\nCol tempo i due fratelli si invaghirono degli insegnamenti e della filosofia della ⟦Scarlet Crusade=Crociata Scarlatta⟧. Avevano sempre mostrato un certo zelo nell'annientare qualunque membro del Flagello incontrassimo nei nostri viaggi, e si sospettava che la loro famiglia avesse legami con l'organizzazione.", "." },
  ["84525795fda1c36b"] = { "Oppure la sanguinite è fatta di sangue? E se sì, il sangue di chi? Il mio? Quello di un umano qualsiasi? Di un animale qualsiasi?\n\nO forse la sanguinite è il sangue di qualcosa di sconosciuto, proprio la cosa che Kegan aveva insieme temuto e venerato quando mi aveva consegnato il suo pendente.\n\nÈ questa la domanda a cui bisogna rispondere. È questa la chiave.", "." },
  ["84604c4221459afe"] = { "Ti mando i miei saluti, {name}. Ero perso nei miei pensieri quando mi sono reso conto che dovevo scriverti.\n\nIn molti, nella nostra cultura, lodano i nostri sciamani come guide spirituali, al pari del nostro grande Capoguerra. Altri ritengono che la spada e l'ascia siano vie ancora più nobili, ma non dimenticare mai che le battaglie, e persino le guerre, si vincono sulle spalle di chi ha abilità più specializzate. È di questo che desidero parlarti, {name}. Cercami in fondo all'Antro del Tirocinio, nella ⟦Valley of Trials=Valle delle Sfide⟧.\n\n-Rwag, istruttore dei ladri", "." },
})
